def load_mutant(old, new):
    src = open(os.path.join(HERE, "policy.py"), encoding="utf-8").read()
    for o, n in (zip(old, new) if isinstance(old, tuple) else [(old, new)]):      # a tuple is a multi-place edit
        if src.count(o) != 1: raise SystemExit(f"mutation anchor not found exactly once: {o[:70]}")
        src = src.replace(o, n)
    mod = types.ModuleType("policy")
    exec(compile(src, "policy_mutant.py", "exec"), mod.__dict__)
    return mod

def main():
    import run_vectors
    missed = 0
    for rule, desc, old, new in MUTATIONS:
        run_vectors.P = load_mutant(old, new)
        buf = io.StringIO()
        with contextlib.redirect_stdout(buf):
            rc = run_vectors.main()
        summary = buf.getvalue().strip().splitlines()[-1]
        caught = rc != 0
        missed += not caught
        print(f"{'caught' if caught else 'MISSED'}  {rule:8} {desc:38} {summary}")
    print(f"{len(MUTATIONS) - missed}/{len(MUTATIONS)} policy mutations caught by the vectors")
    return 1 if missed else 0

if __name__ == "__main__":
    sys.exit(main())
